const now = DateTime.now();
const fmt = 'yyyy-MM-dd';
const currentEnd    = now.minus({ days: 1  }).toFormat(fmt);
const currentStart  = now.minus({ days: 28 }).toFormat(fmt);
const previousEnd   = now.minus({ days: 29 }).toFormat(fmt);
const previousStart = now.minus({ days: 56 }).toFormat(fmt);
return [{ json: { currentStart, currentEnd, previousStart, previousEnd } }];

// ── Collect data from all upstream sources ───────────────────────
const gscRows     = ($('GSC Current Period').first().json.rows  || []);
const gscPrevRows = ($('GSC Previous Period').first().json.rows || []);
const gaRows      = $('GA Current Period').all().map(i => i.json);
const gaPrevRows  = $('GA Previous Period').all().map(i => i.json);

// ── Build lookup maps ────────────────────────────────────────────
const gscCurrByPage = {};
for (const r of gscRows) {
  const pg = r.keys[1];
  if (!gscCurrByPage[pg]) gscCurrByPage[pg] = { clicks: 0, impressions: 0 };
  gscCurrByPage[pg].clicks      += r.clicks;
  gscCurrByPage[pg].impressions += r.impressions;
}

const gscPrevByPage = {};
for (const r of gscPrevRows) {
  const pg = r.keys[1];
  if (!gscPrevByPage[pg]) gscPrevByPage[pg] = { clicks: 0, impressions: 0 };
  gscPrevByPage[pg].clicks      += r.clicks;
  gscPrevByPage[pg].impressions += r.impressions;
}

const gaMap = {};
for (const r of gaRows) gaMap[r.pageLocation] = r;

const gaPrevMap = {};
for (const r of gaPrevRows) gaPrevMap[r.pageLocation] = r;

const seen = new Set();
const opps = [];

const add = (opp) => {
  const key = opp.type + '|' + (opp.query || '') + '|' + opp.page;
  if (!seen.has(key)) { seen.add(key); opps.push(opp); }
};

// ─────────────────────────────────────────────────────────────────
// 1. QUICK WINS — Pages ranking #4-15 with high impressions
// ─────────────────────────────────────────────────────────────────
for (const r of gscRows) {
  if (r.position >= 4 && r.position <= 15 && r.impressions >= 100) {
    add({
      type: 'QUICK_WIN',
      query: r.keys[0],
      page: r.keys[1],
      clicks: r.clicks,
      impressions: r.impressions,
      ctr: +(r.ctr * 100).toFixed(2),
      position: +r.position.toFixed(1),
      metric: r.impressions,
      description: 'Ranking #' + r.position.toFixed(0) + ' for "' + r.keys[0] + '" with ' + r.impressions + ' impressions',
      action: 'Strengthen internal links to this page, improve title tag, build 2-3 quality backlinks to push into top 3',
    });
  }
}

// ─────────────────────────────────────────────────────────────────
// 2. CTR OPPORTUNITIES — High impressions, low CTR
// ─────────────────────────────────────────────────────────────────
for (const r of gscRows) {
  if (r.impressions >= 300 && r.ctr < 0.03 && r.position <= 25) {
    add({
      type: 'CTR_OPPORTUNITY',
      query: r.keys[0],
      page: r.keys[1],
      clicks: r.clicks,
      impressions: r.impressions,
      ctr: +(r.ctr * 100).toFixed(2),
      position: +r.position.toFixed(1),
      metric: r.impressions,
      description: '"' + r.keys[0] + '" — ' + r.impressions + ' impressions but only ' + (r.ctr * 100).toFixed(1) + '% CTR at position ' + r.position.toFixed(0),
      action: 'Rewrite title tag with a power word and number (e.g. "Best X for Y in 2026"), update meta description with clear benefit + CTA',
    });
  }
}

// ─────────────────────────────────────────────────────────────────
// 3. CONTENT DECAY — Pages losing 30%+ clicks vs previous period
// ─────────────────────────────────────────────────────────────────
for (const [pg, curr] of Object.entries(gscCurrByPage)) {
  const prev = gscPrevByPage[pg];
  if (prev && prev.clicks >= 30 && curr.clicks < prev.clicks * 0.7) {
    const drop = Math.round((1 - curr.clicks / prev.clicks) * 100);
    add({
      type: 'CONTENT_DECAY',
      query: '(all queries)',
      page: pg,
      clicks: curr.clicks,
      impressions: curr.impressions,
      ctr: null,
      position: null,
      metric: prev.clicks - curr.clicks,
      description: pg.replace(/^https?:\/\/[^/]+/, '') + ' lost ' + drop + '% clicks (' + prev.clicks + ' \u2192 ' + curr.clicks + ' in 28 days)',
      action: 'Audit for keyword drift and content freshness, check for algorithm updates, verify no technical issues in GSC',
    });
  }
}

// ─────────────────────────────────────────────────────────────────
// 4. KEYWORD CANNIBALIZATION — 2+ pages competing for same query
// ─────────────────────────────────────────────────────────────────
const queryPageMap = {};
for (const r of gscRows) {
  const q = r.keys[0];
  if (!queryPageMap[q]) queryPageMap[q] = [];
  queryPageMap[q].push({ page: r.keys[1], position: r.position, impressions: r.impressions });
}
for (const [q, pages] of Object.entries(queryPageMap)) {
  if (pages.length >= 2) {
    const sorted = [...pages].sort((a, b) => a.position - b.position);
    const totalImps = sorted.reduce((s, p) => s + p.impressions, 0);
    if (totalImps >= 100) {
      add({
        type: 'CANNIBALIZATION',
        query: q,
        page: sorted.slice(0, 2).map(p => p.page).join(' vs '),
        clicks: null,
        impressions: totalImps,
        ctr: null,
        position: +sorted[0].position.toFixed(1),
        metric: totalImps,
        description: '"' + q + '" split across ' + pages.length + ' URLs \u2014 cannibalization detected',
        action: 'Consolidate into single canonical page, or clearly differentiate intent between pages; add internal links to chosen canonical',
      });
    }
  }
}

// ─────────────────────────────────────────────────────────────────
// 5. NEW OPPORTUNITIES — Queries appearing for the first time
// ─────────────────────────────────────────────────────────────────
const prevQuerySet = new Set(gscPrevRows.map(r => r.keys[0]));
for (const r of gscRows) {
  if (!prevQuerySet.has(r.keys[0]) && r.impressions >= 50) {
    add({
      type: 'NEW_OPPORTUNITY',
      query: r.keys[0],
      page: r.keys[1],
      clicks: r.clicks,
      impressions: r.impressions,
      ctr: +(r.ctr * 100).toFixed(2),
      position: +r.position.toFixed(1),
      metric: r.impressions,
      description: 'New query "' + r.keys[0] + '" surfaced for the first time (' + r.impressions + ' impressions)',
      action: 'Create or optimise a dedicated page targeting this query before competitors notice the trend',
    });
  }
}

// ─────────────────────────────────────────────────────────────────
// 6. CONVERSION OPPORTUNITIES — High traffic, low engagement time
// ─────────────────────────────────────────────────────────────────
for (const r of gaRows) {
  const sessions  = parseInt(r.sessions || '0');
  const duration  = parseFloat(r.userEngagementDuration || '0');
  const avgSec    = sessions > 0 ? duration / sessions : 0;
  if (sessions >= 150 && avgSec < 30) {
    add({
      type: 'CONVERSION_OPPORTUNITY',
      query: null,
      page: r.pageLocation,
      clicks: sessions,
      impressions: null,
      ctr: +avgSec.toFixed(0),
      position: null,
      metric: sessions,
      description: r.pageLocation.replace(/^https?:\/\/[^/]+/, '') + ' \u2014 ' + sessions + ' sessions but only ' + avgSec.toFixed(0) + 's avg engagement',
      action: 'Add clear CTA above the fold, improve page structure, add internal links to high-intent pages',
    });
  }
}

// ── Score every opportunity ──────────────────────────────────────
const BASE_SCORE = {
  CONTENT_DECAY: 88,
  QUICK_WIN: 85,
  CONVERSION_OPPORTUNITY: 80,
  CTR_OPPORTUNITY: 75,
  CANNIBALIZATION: 68,
  NEW_OPPORTUNITY: 58,
};

for (const o of opps) {
  const base  = BASE_SCORE[o.type] || 50;
  const boost = Math.min(15, Math.round(Math.log10(Math.max(o.metric || 1, 1)) * 5));
  o.score    = base + boost;
  o.priority = o.score >= 90 ? 'P1' : o.score >= 75 ? 'P2' : 'P3';
  o.date     = new Date().toISOString().slice(0, 10);
}

const ranked = opps.sort((a, b) => b.score - a.score).slice(0, 30);
return ranked.map(o => ({ json: o }));

const opps  = $input.all().map(i => i.json);
const today = new Date().toDateString();

const lines = opps.slice(0, 20).map((o, idx) => {
  const pos = o.position != null ? ' | Position: ' + o.position : '';
  const ctr = o.ctr != null     ? ' | CTR: ' + o.ctr + '%'      : '';
  const imp = o.impressions != null ? ' | Impressions: ' + o.impressions : '';
  return (idx + 1) + '. [' + o.priority + '] [' + o.type + '] Score:' + o.score +
    '\n   Query: ' + (o.query || 'N/A') +
    '\n   Page:  ' + o.page +
    '\n   Data: Clicks:' + (o.clicks || 'N/A') + imp + ctr + pos +
    '\n   Signal: ' + o.description +
    '\n   Suggested action: ' + o.action;
}).join('\n\n');

const p1Count = opps.filter(o => o.priority === 'P1').length;
const p2Count = opps.filter(o => o.priority === 'P2').length;
const p3Count = opps.filter(o => o.priority === 'P3').length;

const typeBreakdown = {};
for (const o of opps) { typeBreakdown[o.type] = (typeBreakdown[o.type] || 0) + 1; }
const breakdown = Object.entries(typeBreakdown).map(([k, v]) => v + ' ' + k).join(', ');

const prompt = 'You are an expert SEO strategist. I have run an automated SEO signal analysis for today (' + today + ').' +
  ' ' + opps.length + ' opportunities were found: P1=' + p1Count + ', P2=' + p2Count + ', P3=' + p3Count + '.' +
  ' Breakdown: ' + breakdown + '.\n\n' +
  'PRIORITIZED OPPORTUNITY BACKLOG:\n' + lines + '\n\n' +
  'Please produce a concise SEO Action Plan with these exact sections:\n' +
  '## Executive Summary\n(2-3 sentences on overall SEO health and biggest threats/wins)\n\n' +
  '## Top 5 Priority Actions This Week\n(numbered, specific, achievable, data-referenced)\n\n' +
  '## 30-Day Roadmap\n(medium-term recommendations beyond the weekly sprint)\n\n' +
  '## What to Deprioritize\n(one thing to stop or defer to protect focus)\n\n' +
  'Be specific. Reference the actual queries, pages, and numbers from the data above. Be direct \u2014 no filler.';

return [{ json: { prompt, opportunityCount: opps.length, p1Count, p2Count, p3Count } }];
